322:     this.towers = this.towers.filter(x => x !== t);
323:     this.selected = null;
324:     this.effects.push({ kind: 'ring', x: t.x, y: t.y, r: 12 * this.S, maxR: 40 * this.S, color: '#ffce7a', width: 2, life: 0.45, max: 0.45 });
325:     this.effects.push({ kind: 'text', x: t.x, y: t.y - 10, text: `+${value}`, color: '#ffe2a0', size: 13 * this.S, life: 0.8, max: 0.8 });
326:     this.spark(t.x, t.y, 8, '#ffce7a', 2);
327:     this.audio.sell();
328:     return { ok: true, value };
329:   }
330: 
331:   cycleTarget() {
332:     if (!this.selected) return;
333:     const i = TARGET_MODES.findIndex(m => m.id === this.selected.mode);
334:     this.selected.mode = TARGET_MODES[(i + 1) % TARGET_MODES.length].id;
335:     this.audio.ui();
336:   }
337: 
338:   /* ---------------- waves ---------------- */
339: 
340:   startWave() {
341:     if (!this.started || this.paused || this.waveActive) return false;
342:     if (this.phase !== 'build') return false;
343:     const specs = makeWave(this.waveNumber, this.map.id);
344:     let last = 0;
345:     this.spawnQueue = specs.map(s => {
346:       const gap = Math.max(0.08, s.delay - last);
347:       last = s.delay;
348:       return { ...s, gap };
349:     });
350:     this.spawnTimer = this.spawnQueue.length ? this.spawnQueue[0].gap : 0.5;
351:     this.waveTotal = this.spawnQueue.length;
352:     this.waveSpawned = 0;
353:     this.waveActive = true;
354:     this.phase = 'wave';
355:     this.bossRef = null;
356:     this.audio.waveStart();
357:     this.effects.push({ kind: 'ring', x: this.spawnPoint[0], y: this.spawnPoint[1], r: 8 * this.S, maxR: 64 * this.S, color: '#ff8a63', width: 2, life: 0.7, max: 0.7 });
358:     this.callbacks.onWaveStart?.(this.waveNumber);
359:     if (this.waveNumber === this.map.waves && !this.endless) {
360:       this.callbacks.toast?.(this.map.flavor?.final || 'Final wave — hold the relay!', 'bad');
361:     } else if (this.waveNumber % 10 === 0) {
362:       this.callbacks.toast?.(this.map.flavor?.boss || 'Enemy commander inbound', 'bad');
363:     }
364:     return true;
365:   }
366: 
367:   spawnEnemy(spec) {
368:     const def = ENEMY_TYPES[spec.type];
369:     const e = {
370:       id: this.uid++,
371:       type: spec.type,
372:       hp: spec.hp,
373:       maxHp: spec.hp,
374:       speed: spec.speed * (0.95 + Math.random() * 0.1),
375:       t: 0,
376:       x: this.pathPts[0][0],
377:       y: this.pathPts[0][1],
378:       angle: 0,
379:       radius: def.radius,
380:       slowT: 0,
381:       slowFactor: 0,
382:       hitFlash: 0,
383:       phase: Math.random() * TAU,
384:       dead: false,
385:       reward: enemyReward(spec.type, this.waveNumber),
386:       leak: def.leak,
387:       isBoss: !!def.boss,
388:     };
389:     this.positionEnemy(e);
390:     this.enemies.push(e);
391:     this.waveSpawned++;
392:     if (e.isBoss) {
393:       this.bossRef = e;
394:       this.audio.bossWarn();
395:       this.shake = Math.max(this.shake, 5);
396:       this.callbacks.onBoss?.();
397:       this.callbacks.toast?.(`${def.name} on the field`, 'bad');
398:       this.effects.push({ kind: 'ring', x: e.x, y: e.y, r: 10 * this.S, maxR: 90 * this.S, color: '#ff8a63', width: 3, life: 0.7, max: 0.7 });
399:     }
400:   }
401: 
402:   positionEnemy(e) {
403:     const n = this.pathPts.length;
404:     if (!n) return;
405:     const f = clamp(e.t, 0, 1) * (n - 1);
406:     const i0 = Math.min(n - 1, Math.floor(f));
407:     const i1 = Math.min(n - 1, i0 + 1);
408:     const frac = f - i0;
409:     const a = this.pathPts[i0];
410:     const b = this.pathPts[i1];
411:     e.x = a[0] + (b[0] - a[0]) * frac;
412:     e.y = a[1] + (b[1] - a[1]) * frac;
413:     e.angle = Math.atan2(b[1] - a[1], b[0] - a[0]);
414:   }
415: 
416:   completeWave() {
417:     if (!this.waveActive) return;
418:     this.waveActive = false;
419:     this.spawnQueue = null;
420:     const bonus = waveReward(this.waveNumber);
421:     this.credits += bonus;
422:     this.creditsEarned += bonus;
423:     this.audio.waveClear();
424:     this.callbacks.toast?.(`Wave ${this.waveNumber} cleared  +${bonus} credits`, 'good');
425:     this.effects.push({ kind: 'ring', x: this.map.base.x * this.w, y: this.map.base.y * this.h, r: 12 * this.S, maxR: 90 * this.S, color: '#8ff0b0', width: 2, life: 0.8, max: 0.8 });
426: 
427:     if (!this.endless && this.waveNumber >= this.map.waves) {
428:       this.win();
429:       return;
430:     }
431:     this.waveNumber++;
432:     this.phase = 'build';
433:     this.selected = null;
434:     this.callbacks.onWaveClear?.(this.waveNumber, bonus);
435:   }
436: 
437:   win() {
438:     if (this.phase === 'victory') return;
439:     this.phase = 'victory';
440:     this.waveActive = false;
441:     this.audio.victory();
442:     this.callbacks.onEnd?.(true);
443:   }
444: 
445:   defeat() {
446:     if (this.phase === 'defeat') return;
447:     this.phase = 'defeat';
448:     this.waveActive = false;
449:     this.audio.defeat();
450:     this.shake = 16;
451:     this.callbacks.onEnd?.(false);
452:   }
453: 
454:   continueEndless() {
455:     this.endless = true;
456:     this.phase = 'build';
457:     if (this.waveNumber <= this.map.waves) this.waveNumber = this.map.waves + 1;
458:     this.lives = Math.max(this.lives, 10);
459:     this.selected = null;
460:     this.paused = false;
461:     this.callbacks.toast?.('Endless mode — the enemy army is endless too', 'bad');
462:   }
463: 
464:   /* ---------------- update ---------------- */
465: 
466:   update(rawDt) {
467:     const rdt = Math.min(rawDt, 0.15);
468:     this.realTime += rdt;
469:     if (!this.started || this.paused || this.phase === 'victory' || this.phase === 'defeat') {
470:       this.updateFx(rdt);
471:       return;
472:     }
473:     // Fixed substeps keep the simulation real-time even at low frame rates.
474:     const total = rdt * this.speed;
475:     const steps = Math.max(1, Math.ceil(total / 0.033));
476:     const dt = total / steps;
477:     for (let i = 0; i < steps; i++) {
478:       this.stepSim(dt);
479:       if (this.phase === 'victory' || this.phase === 'defeat') break;
480:     }
481:   }
482: 
483:   stepSim(dt) {
484:     this.time += dt;
485: 
486:     // ambient weather
487:     this.dustTimer -= dt;
488:     if (this.dustTimer <= 0) {
489:       const amb = this.theme.ambient || { mode: 'dust', color: 'rgba(255, 233, 185, 0.35)', density: 1 };
490:       this.dustTimer = (0.35 + Math.random() * 0.5) / (amb.density || 1);
491:       if (this.particles.length < 300) {
492:         const w = this.w;
493:         const h = this.h;
494:         const S = this.S;
495:         let p;
496:         if (amb.mode === 'snow') {
497:           p = {
498:             x: Math.random() * w * 1.1,
499:             y: -10,
500:             vx: (6 + Math.random() * 18) * S,
501:             vy: (26 + Math.random() * 42) * S,
502:             life: 5 + Math.random() * 4,
503:             max: 9,
504:             size: (0.8 + Math.random() * 1.9) * S,
505:             color: amb.color,
506:             glow: Math.random() > 0.6,
507:             gravity: 0,
508:             drag: 0.998,
509:           };
510:         } else if (amb.mode === 'ember') {
511:           p = {
512:             x: Math.random() * w,
513:             y: h * (0.4 + Math.random() * 0.7),
514:             vx: (6 + Math.random() * 22) * S,
515:             vy: -(14 + Math.random() * 34) * S,
516:             life: 2 + Math.random() * 3,
517:             max: 5,
518:             size: (0.7 + Math.random() * 1.6) * S,
519:             color: amb.color,
520:             glow: true,
521:             gravity: -6,
522:             drag: 0.995,
523:           };
524:         } else if (amb.mode === 'mote') {
525:           p = {
526:             x: Math.random() * w,
527:             y: h * (0.3 + Math.random() * 0.7),
528:             vx: (4 + Math.random() * 14) * S,
529:             vy: -(2 + Math.random() * 12) * S,
530:             life: 3 + Math.random() * 3,
531:             max: 6,
532:             size: (0.7 + Math.random() * 1.3) * S,
533:             color: amb.color,
534:             glow: true,
535:             gravity: 0,
536:             drag: 0.997,
537:           };
538:         } else {
539:           p = {
540:             x: Math.random() * w,
541:             y: h * (0.25 + Math.random() * 0.7),
542:             vx: (10 + Math.random() * 26) * S,
543:             vy: (2 + Math.random() * 8) * S,
544:             life: 3.5 + Math.random() * 4,
545:             max: 7,
546:             size: (0.7 + Math.random() * 1.2) * S,
547:             color: amb.color,
548:             glow: false,
549:             gravity: 0,
550:             drag: 0.99,
551:           };
552:         }
553:         this.particles.push(p);
554:       }
555:     }
556: 
557:     if (this.waveActive && this.spawnQueue) {
558:       this.spawnTimer -= dt;
559:       let guard = 0;
560:       while (this.spawnTimer <= 0 && this.spawnQueue.length && guard++ < 20) {
561:         const spec = this.spawnQueue.shift();
562:         this.spawnEnemy(spec);
563:         this.spawnTimer += this.spawnQueue.length ? this.spawnQueue[0].gap : 0.5;
564:       }
565:     }
566: 
567:     this.updateEnemies(dt);
568:     this.updateTowers(dt);
569:     this.updateProjectiles(dt);
570:     this.updateFx(dt);
571:     this.cleanup();
572: 
573:     if (this.waveActive && (!this.spawnQueue || this.spawnQueue.length === 0) && this.enemies.length === 0) {
574:       this.completeWave();
575:     }
576:     if (this.baseFlash > 0) this.baseFlash = Math.max(0, this.baseFlash - dt * 2);
577:     if (this.shake > 0) this.shake = Math.max(0, this.shake - dt * 34);
578:   }
579: 
580:   updateFx(dt) {
581:     for (const e of this.effects) e.life -= dt;
582:     for (const p of this.particles) {
583:       p.life -= dt;
584:       p.x += p.vx * dt;
585:       p.y += p.vy * dt;
586:       if (p.gravity) p.vy += p.gravity * dt;
587:       if (p.drag) { p.vx *= p.drag; p.vy *= p.drag; }
588:     }
589:     this.effects = this.effects.filter(e => e.life > 0);
590:     this.particles = this.particles.filter(p => p.life > 0 && p.x > -80 && p.x < this.w + 80 && p.y > -80 && p.y < this.h + 80);
591:   }
592: 
593:   updateEnemies(dt) {
594:     for (const e of this.enemies) {
595:       if (e.dead) continue;
596:       if (e.hitFlash > 0) e.hitFlash = Math.max(0, e.hitFlash - dt);
597:       if (e.slowT > 0) {
598:         e.slowT -= dt;
599:         if (e.slowT <= 0) { e.slowT = 0; e.slowFactor = 0; }
600:       }
601:       const slowMul = e.slowT > 0 ? 1 - e.slowFactor : 1;
602:       const pxPerSec = e.speed * this.S * slowMul;
603:       e.t += (pxPerSec * dt) / this.pathLen;
604:       if (e.t >= 1) {
605:         e.dead = true;
606:         this.leakEnemy(e);
607:       } else {
608:         this.positionEnemy(e);
609:       }
610:     }
611:   }
612: 
613:   leakEnemy(e) {
614:     this.lives -= e.leak;
615:     this.baseFlash = 1;
616:     this.shake = Math.max(this.shake, 8);
617:     this.audio.leak();
618:     this.effects.push({ kind: 'ring', x: this.map.base.x * this.w, y: this.map.base.y * this.h, r: 20 * this.S, maxR: 105 * this.S, color: '#ff6e58', width: 3, life: 0.7, max: 0.7 });
619:     this.effects.push({ kind: 'flash', x: this.map.base.x * this.w, y: this.map.base.y * this.h, r: 100 * this.S, color: 'rgba(255, 90, 70, 0.5)', life: 0.5, max: 0.5 });
620:     this.callbacks.toast?.(`Relay hit!  −${e.leak} integrity`, 'bad');
621:     this.callbacks.onLeak?.(e.leak);
622:     if (this.bossRef === e) this.bossRef = null;
623:     if (this.lives <= 0) {
624:       this.lives = 0;
625:       this.defeat();
626:     }
627:     if (this.phase === 'defeat') {
628:       // let the current frame finish; game over overlay takes over
629:     }
630:   }
631: 
632:   updateTowers(dt) {
633:     for (const t of this.towers) {
634:       if (t.flash > 0) t.flash = Math.max(0, t.flash - dt * 3);
635:       t.cooldownLeft -= dt;
636:       t.recoil = Math.max(0, t.recoil - dt * 7);
637:       const target = this.pickTarget(t);
638:       if (target) {
639:         const desired = Math.atan2(target.y - t.y, target.x - t.x);
640:         t.targetAngle = desired;
641:         t.angle = angleLerp(t.angle, desired, dt * 16);
642:         if (t.cooldownLeft <= 0) {
643:           this.fire(t, target);
644:           t.cooldownLeft = t.cooldown;
645:         }
646:       } else {
647:         t.targetAngle = t.angle;
648:         t.angle += dt * 0.18;
649:       }
650:     }
651:   }
652: 
653:   pickTarget(t) {
654:     const R2 = (t.range * this.S) ** 2;
655:     let best = null;
656:     let bestScore = -Infinity;
657:     for (const e of this.enemies) {
658:       if (e.dead) continue;
659:       const d2 = (e.x - t.x) ** 2 + (e.y - t.y) ** 2;
660:       if (d2 > R2) continue;
661:       let score;
662:       if (t.mode === 'first') score = e.t;
663:       else if (t.mode === 'last') score = -e.t;
664:       else if (t.mode === 'strong') score = e.hp;
665:       else score = -d2;
666:       if (score > bestScore) { bestScore = score; best = e; }
667:     }
668:     return best;
669:   }
670: 
671:   muzzle(t, target) {
672:     const a = Math.atan2(target.y - t.y, target.x - t.x);
673:     const d = (t.type === 'bounty' ? 23 : 17) * this.S;
674:     return { x: t.x + Math.cos(a) * d, y: t.y + Math.sin(a) * d, angle: a };
675:   }
676: 
677:   fire(t, target) {
678:     const def = TOWERS[t.type];
679:     const muzzle = this.muzzle(t, target);
680:     t.recoil = 1;
681:     t.flash = 0.4;
682:     if (def.attack === 'bullet') {
683:       this.projectiles.push({
684:         kind: 'bullet', x: muzzle.x, y: muzzle.y, target,
685:         speed: def.projectileSpeed * this.S, damage: t.damage,
686:         towerType: t.type, life: 2.4, angle: muzzle.angle,
687:       });
688:       this.audio.shot('scout');
689:       this.effects.push({ kind: 'flash', x: muzzle.x, y: muzzle.y, r: 11 * this.S, color: 'rgba(255, 220, 130, 0.55)', life: 0.08, max: 0.08 });
690:       this.spark(muzzle.x, muzzle.y, 2, '#ffd77f', 1.6);
691:     } else if (def.attack === 'rocket') {
692:       this.projectiles.push({
693:         kind: 'rocket', x: muzzle.x, y: muzzle.y, target,
694:         speed: def.projectileSpeed * this.S, damage: t.damage,
695:         splash: t.splash * this.S, towerType: t.type, life: 3.4, angle: muzzle.angle, source: { x: t.x, y: t.y },
696:       });
697:       this.audio.shot('rocket');
698:       this.spark(muzzle.x, muzzle.y, 4, '#ffb066', 2.2);
699:     } else if (def.attack === 'ion') {
700:       this.projectiles.push({
701:         kind: 'ion', x: muzzle.x, y: muzzle.y, target,
702:         speed: def.projectileSpeed * this.S, damage: t.damage,
703:         slow: t.slow, slowDuration: t.slowDuration, splash: 36 * this.S,
704:         towerType: t.type, life: 3, angle: muzzle.angle, spin: 0,
705:         source: { x: t.x, y: t.y },
706:       });
707:       this.audio.shot('ion');
708:       this.effects.push({ kind: 'flash', x: muzzle.x, y: muzzle.y, r: 16 * this.S, color: 'rgba(130, 230, 255, 0.6)', life: 0.14, max: 0.14 });
709:     } else if (def.attack === 'laser') {
710:       const hits = [target];
711:       const extra = (t.chain || 1) - 1;
712:       if (extra > 0) {
713:         const near = this.enemies
714:           .filter(e => !e.dead && e !== target && Math.hypot(e.x - target.x, e.y - target.y) < 95 * this.S && Math.hypot(e.x - t.x, e.y - t.y) < t.range * this.S)
715:           .sort((a, b) => Math.hypot(a.x - target.x, a.y - target.y) - Math.hypot(b.x - target.x, b.y - target.y));
716:         for (let i = 0; i < extra && i < near.length; i++) hits.push(near[i]);
717:       }
718:       let fx = muzzle;
719:       for (const e of hits) {
720:         this.effects.push({ kind: 'beam', x1: fx.x, y1: fx.y, x2: e.x, y2: e.y, color: '#ff6252', width: 3.1 * this.S, life: 0.11, max: 0.11 });
721:         this.damageEnemy(e, t.damage, { tower: t });
722:         this.spark(e.x, e.y, 3, '#ffab7f', 2.4);
723:         fx = { x: e.x, y: e.y };
724:       }
725:       this.audio.shot('laser');
726:       this.effects.push({ kind: 'flash', x: muzzle.x, y: muzzle.y, r: 14 * this.S, color: 'rgba(255, 110, 90, 0.5)', life: 0.1, max: 0.1 });
727:     } else if (def.attack === 'sniper') {
728:       const bonus = ENEMY_TYPES[target.type].boss ? def.bossBonus : 1;
729:       const dmg = t.damage * bonus;
730:       this.effects.push({ kind: 'beam', x1: muzzle.x, y1: muzzle.y, x2: target.x, y2: target.y, color: '#ffce7c', width: 2.2 * this.S, life: 0.16, max: 0.16 });
731:       this.effects.push({ kind: 'flash', x: target.x, y: target.y, r: 22 * this.S, color: 'rgba(255, 220, 150, 0.55)', life: 0.18, max: 0.18 });
732:       this.damageEnemy(target, dmg, { tower: t });
733:       this.spark(target.x, target.y, 8, '#ffd98a', 2.8);
734:       this.audio.shot('sniper');
735:       this.shake = Math.max(this.shake, ENEMY_TYPES[target.type].boss ? 2.5 : 0.7);
736:     } else if (def.attack === 'aura') {
737:       const R2 = (t.range * this.S) ** 2;
738:       let hurt = 0;
739:       for (const e of this.enemies) {
740:         if (e.dead) continue;
741:         if ((e.x - t.x) ** 2 + (e.y - t.y) ** 2 < R2) {
742:           this.damageEnemy(e, t.damage, { tower: t });
743:           hurt++;
744:         }
745:       }
746:       const slashAngle = this.time * 3 + t.phase;
747:       this.effects.push({ kind: 'slash', x: t.x, y: t.y, r: t.range * this.S * 0.92, a0: slashAngle, a1: slashAngle + 1.9, color: '#8fd6ff', width: 3 * this.S, life: 0.16, max: 0.16 });
748:       if (hurt > 0) this.audio.shot('jedi');
749:     }
750:   }
751: 
752:   damageEnemy(e, amount, opts = {}) {
753:     if (e.dead) return;
754:     const def = ENEMY_TYPES[e.type];
755:     let dmg = amount;
756:     if (!opts.trueDamage) dmg = Math.max(1, dmg - (def.armor || 0));
757:     e.hp -= dmg;
758:     e.hitFlash = 0.1;
759:     if (e.hp <= 0) this.killEnemy(e, opts.tower);
760:   }
761: 
762:   killEnemy(e, tower) {
763:     if (e.dead) return;
764:     e.dead = true;
765:     this.kills++;
766:     this.credits += e.reward;
767:     this.creditsEarned += e.reward;
768:     const edef = ENEMY_TYPES[e.type];
769:     const big = !!edef.boss || !!edef.heavy;
770:     this.audio.kill(big);
771:     this.spark(e.x, e.y, big ? 14 : 7, edef.boss ? '#ff8a6a' : edef.heavy ? '#ffb36b' : edef.color || '#ffb36b', big ? 3 : 2);
772:     if (edef.boss) {
773:       this.explosion(e.x, e.y, 100 * this.S, true);
774:       this.shake = Math.max(this.shake, 12);
775:       this.effects.push({ kind: 'text', x: e.x, y: e.y - 20 * this.S, text: `+${e.reward}`, color: '#ffe6a1', size: 16 * this.S, life: 1.1, max: 1.1 });
776:       this.callbacks.toast?.(`${edef.name} destroyed  +${e.reward} credits`, 'good');
777:       this.bossRef = null;
778:     } else if (edef.heavy) {
779:       this.explosion(e.x, e.y, 26 * this.S, false);
780:     } else {
781:       this.effects.push({ kind: 'ring', x: e.x, y: e.y, r: 2, maxR: 14 * this.S, color: 'rgba(255, 190, 110, 0.7)', width: 1.2, life: 0.25, max: 0.25, alpha: 0.5 });
782:     }
783:     // gold flecks
784:     this.spark(e.x, e.y, 3, '#ffe08a', 1.5);
785:     void tower;
786:   }
