156:     pebbleLit: 'rgba(192, 216, 152, 0.26)',
157:     pad: '#7d8178',
158:     padEdge: '#4f544c',
159:     dome: ['#b4bcae', '#7d8778', '#525b4d'],
160:     vignette: 'rgba(5, 16, 6, 0.46)',
161:     ambient: { mode: 'mote', color: 'rgba(220, 255, 170, 0.40)', density: 1 },
162:   },
163: };
164: 
165: export function getTheme(name) {
166:   return THEMES[name] || THEMES.desert;
167: }
168: 
169: export function mulberry32(a) {
170:   return function () {
171:     a |= 0;
172:     a = (a + 0x6d2b79f5) | 0;
173:     let t = Math.imul(a ^ (a >>> 15), 1 | a);
174:     t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
175:     return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
176:   };
177: }
178: 
179: function roundRect(ctx, x, y, w, h, r) {
180:   const rr = Math.min(r, Math.abs(w) / 2, Math.abs(h) / 2);
181:   ctx.beginPath();
182:   ctx.moveTo(x + rr, y);
183:   ctx.arcTo(x + w, y, x + w, y + h, rr);
184:   ctx.arcTo(x + w, y + h, x, y + h, rr);
185:   ctx.arcTo(x, y + h, x, y, rr);
186:   ctx.arcTo(x, y, x + w, y, rr);
187:   ctx.closePath();
188: }
189: 
190: function tracePoints(ctx, pts) {
191:   if (!pts.length) return;
192:   ctx.beginPath();
193:   ctx.moveTo(pts[0][0], pts[0][1]);
194:   for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i][0], pts[i][1]);
195: }
196: 
197: function offsetPath(pts, off) {
198:   const out = [];
199:   for (let i = 0; i < pts.length; i++) {
200:     const p = pts[i];
201:     const prev = pts[Math.max(0, i - 1)];
202:     const next = pts[Math.min(pts.length - 1, i + 1)];
203:     let dx = next[0] - prev[0];
204:     let dy = next[1] - prev[1];
205:     const l = Math.hypot(dx, dy) || 1;
206:     dx /= l; dy /= l;
207:     out.push([p[0] - dy * off, p[1] + dx * off]);
208:   }
209:   return out;
210: }
