397: function hashString(s) {
398:   let h = 2166136261;
399:   for (let i = 0; i < s.length; i++) {
400:     h ^= s.charCodeAt(i);
401:     h = Math.imul(h, 16777619);
402:   }
403:   return h >>> 0;
404: }
