618: function drawSpawnCave(ctx, w, h, S, rng, theme, pathPts) {
619:   const start = (pathPts && pathPts[0]) || [0, h * 0.64];
620:   const cx = start[0] - 10 * S;
621:   const cy = start[1];
622:   const style = theme.caveStyle;
623: 
624:   ctx.save();
625:   if (style === 'bunker') {
626:     drawBunkerGate(ctx, cx, cy, S, rng, theme);
627:     ctx.restore();
628:     return;
629:   }
630: 
631:   const rx = (style === 'lava' ? 70 : 62) * S;
632:   const ry = (style === 'lava' ? 46 : 42) * S;
633: 
634:   // outer shadow and bank
635:   ctx.fillStyle = style === 'lava' ? 'rgba(0, 0, 0, 0.45)' : 'rgba(26, 42, 52, 0.28)';
636:   ctx.beginPath();
637:   ctx.ellipse(cx + 18 * S, cy + 8 * S, rx * 1.06, ry * 1.04, -0.06, 0, TAU);
638:   ctx.fill();
639: 
640:   const rim = ctx.createLinearGradient(0, cy - ry, 0, cy + ry);
641:   rim.addColorStop(0, theme.caveRim[0]);
642:   rim.addColorStop(0.5, theme.caveRim[1]);
643:   rim.addColorStop(1, theme.caveRim[2]);
