833: function distanceToPath(x, y, pts) {
834:   let best = Infinity;
835:   for (let i = 0; i < pts.length - 1; i++) {
836:     const ax = pts[i][0], ay = pts[i][1], bx = pts[i + 1][0], by = pts[i + 1][1];
837:     const dx = bx - ax, dy = by - ay;
838:     const l2 = dx * dx + dy * dy || 1;
839:     let t = ((x - ax) * dx + (y - ay) * dy) / l2;
840:     t = clamp(t, 0, 1);
841:     const px = ax + dx * t, py = ay + dy * t;
842:     best = Math.min(best, Math.hypot(x - px, y - py));
843:   }
844:   return best;
845: }
