  // Snout, nostrils and mouth line.
  ctx.fillStyle = 'rgba(227, 201, 158, 0.4)';
  ctx.beginPath();
  ctx.ellipse(28.2, 0, 3.0, 4.2, 0, 0, TAU);
  ctx.fill();
  ctx.fillStyle = '#3b2716';
  for (const side of [-1, 1]) {
    ctx.beginPath();
    ctx.ellipse(29.9, side * 1.55, 0.72, 0.44, side * 0.3, 0, TAU);
    ctx.fill();
  }
  ctx.strokeStyle = '#4b3019';
  ctx.lineWidth = 0.8;
  ctx.beginPath();
  ctx.moveTo(28.0, 0);
  ctx.quadraticCurveTo(30.6, 0, 31.2, 0);
