+  // Four stout legs with broad hooves.
+  const legs = [
+    { x: 9.5, y: -8.0, kx: 12.2, ky: -14.4, fx: 12.8, fy: -19.6, s: gait },
+    { x: 9.5, y: 8.0, kx: 12.2, ky: 14.4, fx: 12.8, fy: 19.6, s: -gait },
+    { x: -10.5, y: -8.0, kx: -13.0, ky: -14.2, fx: -13.6, fy: -19.2, s: -gaitB },
