  const strideB = Math.sin(time * 15.5 + p + 1.9);
  const tailWave = Math.sin(time * 7.4 + p);
  const tailWave2 = Math.sin(time * 7.4 + p - 0.9);

  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  // Thick, bare tail sweeping behind the rump.
  ctx.strokeStyle = '#a97c68';
  ctx.lineWidth = 2.9;
  ctx.beginPath();
  ctx.moveTo(-9.0, 0.1);
  ctx.quadraticCurveTo(-14.0, tailWave * 1.6, -19.0, tailWave * 3.8);
  ctx.stroke();
  ctx.lineWidth = 1.9;
  ctx.beginPath();
  ctx.moveTo(-18.6, tailWave * 3.7);
  ctx.quadraticCurveTo(-22.6, tailWave * 4.8, -26.8, tailWave2 * 6.0);
  ctx.stroke();
  ctx.strokeStyle = 'rgba(232, 184, 156, 0.4)';
  ctx.lineWidth = 0.6;
  ctx.beginPath();
  ctx.moveTo(-9.6, 0.0);
  ctx.quadraticCurveTo(-14.4, tailWave * 1.5, -19.4, tailWave * 3.6);
  ctx.stroke();

  // Short, tucked paws. Four legs, but close to the body so it reads
  // as a scurrying rodent rather than an insect.
  const legs = [
    { x: 4.0, y: -3.6, ex: 5.7, ey: -6.1, fx: 6.5, fy: -8.1, s: stride },
    { x: 4.0, y: 3.6, ex: 5.7, ey: 6.1, fx: 6.5, fy: 8.1, s: -stride },
    { x: -6.3, y: -3.9, ex: -7.8, ey: -6.6, fx: -8.5, fy: -8.8, s: -strideB },
    { x: -6.3, y: 3.9, ex: -7.8, ey: 6.6, fx: -8.5, fy: 8.8, s: strideB },
  ];
  for (const leg of legs) {
    const dx = leg.s * 0.75;
    ctx.strokeStyle = '#6e5744';
    ctx.lineWidth = 3.0;
    ctx.beginPath();
    ctx.moveTo(leg.x, leg.y);
    ctx.lineTo(leg.ex + dx * 0.5, leg.ey);
    ctx.lineTo(leg.fx + dx, leg.fy);
    ctx.stroke();
    ctx.fillStyle = '#5e4a3b';
    ctx.beginPath();
    ctx.ellipse(leg.fx + dx, leg.fy, 1.8, 1.25, Math.atan2(leg.fy, leg.fx), 0, TAU);
    ctx.fill();
  }

  // Broad, hunched torso with a high shoulder hump and narrow rump.
  const body = ctx.createLinearGradient(-7, -8, 6, 8);
  body.addColorStop(0, '#bda286');
  body.addColorStop(0.46, '#9a8067');
  body.addColorStop(1, '#6d5745');
  ctx.fillStyle = body;
  ctx.beginPath();
  ctx.moveTo(-9.8, 0);
  ctx.bezierCurveTo(-10.0, -5.0, -5.0, -7.1, 0.4, -6.5);
  ctx.bezierCurveTo(4.6, -6.0, 7.4, -4.3, 7.9, -2.0);
  ctx.lineTo(7.9, 2.0);
  ctx.bezierCurveTo(7.4, 4.3, 4.6, 6.0, 0.4, 6.5);
  ctx.bezierCurveTo(-5.0, 7.1, -10.0, 5.0, -9.8, 0);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = 'rgba(68, 49, 36, 0.5)';
  ctx.lineWidth = 0.65;
  ctx.stroke();

  // Scruffy fur silhouette: short, irregular tufts.
  const furCols = ['rgba(91, 71, 54, 0.85)', 'rgba(182, 158, 128, 0.65)', 'rgba(119, 96, 73, 0.8)'];
  for (let i = 0; i < 20; i++) {
