    { x: -10.2, y: -6.6, kx: -11.2, kx2: -11.8, ky: -10.3, fx: -12.1, fy: -12.4, s: -gaitB },
    { x: -10.2, y: 6.6, kx: -11.2, kx2: -11.8, ky: 10.3, fx: -12.1, fy: 12.4, s: gaitB },
  ];
  for (const leg of legs) {
    const swing = leg.s * 1.2;
    const dir = Math.sign(leg.y);
    // upper leg, shaggy at the shoulder
    ctx.strokeStyle = '#3d291b';
    ctx.lineWidth = 7.4;
    ctx.beginPath();
    ctx.moveTo(leg.x, leg.y);
    ctx.lineTo(leg.kx + swing * 0.3, leg.ky);
    ctx.stroke();
    ctx.strokeStyle = 'rgba(104, 72, 48, 0.75)';
    ctx.lineWidth = 2.0;
    ctx.beginPath();
    ctx.moveTo(leg.x + 1.6, leg.y - dir * 1.0);
    ctx.lineTo(leg.kx + swing * 0.3 + 1.4, leg.ky - dir * 0.8);
    ctx.stroke();
    // knee and lower leg
    ctx.fillStyle = '#352317';
    ctx.beginPath();
    ctx.ellipse(leg.kx + swing * 0.3, leg.ky, 3.6, 2.8, 0, 0, TAU);
    ctx.fill();
    ctx.strokeStyle = '#332115';
    ctx.lineWidth = 5.0;
    ctx.beginPath();
    ctx.moveTo(leg.kx2 + swing * 0.55, leg.ky);
    ctx.lineTo(leg.fx + swing, leg.fy);
    ctx.stroke();
    // broad hoof
    ctx.fillStyle = '#20140d';
    ctx.beginPath();
    ctx.ellipse(leg.fx + swing, leg.fy, 3.9, 2.3, Math.atan2(leg.fy, leg.fx), 0, TAU);
    ctx.fill();
    ctx.strokeStyle = 'rgba(150, 113, 78, 0.6)';
    ctx.lineWidth = 0.55;
    ctx.beginPath();
    ctx.moveTo(leg.fx + swing - 1.7, leg.fy);
    ctx.lineTo(leg.fx + swing + 1.7, leg.fy);
    ctx.stroke();
    // shaggy fringe over the knee
    ctx.strokeStyle = 'rgba(30, 18, 11, 0.8)';
    ctx.lineWidth = 0.9;
    for (let i = -1; i <= 1; i++) {
      ctx.beginPath();
      ctx.moveTo(leg.kx + swing * 0.3 + i * 1.7, leg.ky + dir * 1.2);
      ctx.lineTo(leg.kx + swing * 0.3 + i * 2.0, leg.ky + dir * 3.4);
      ctx.stroke();
    }
  }

  // Massive barrel body with a high shoulder hump and heavy rump.
  const body = ctx.createLinearGradient(-8, -11, 17, 11);
  body.addColorStop(0, '#5b3f2a');
  body.addColorStop(0.34, '#472f1f');
  body.addColorStop(0.72, '#3a2618');
  body.addColorStop(1, '#2a1a10');
  ctx.fillStyle = body;
  ctx.beginPath();
  ctx.moveTo(-18.0, 0);
  ctx.bezierCurveTo(-18.2, -6.6, -13.6, -10.0, -6.2, -10.2);
  ctx.bezierCurveTo(0.8, -10.4, 6.8, -10.0, 10.6, -7.6);
  ctx.bezierCurveTo(14.0, -5.5, 15.8, -2.7, 16.0, 0);
  ctx.bezierCurveTo(15.8, 2.7, 14.0, 5.5, 10.6, 7.6);
  ctx.bezierCurveTo(6.8, 10.0, 0.8, 10.4, -6.2, 10.2);
  ctx.bezierCurveTo(-13.6, 10.0, -18.2, 6.6, -18.0, 0);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = '#180e08';
  ctx.lineWidth = 1.15;
  ctx.stroke();

  // Shaggy coat fringe: short, irregular clumps along the flanks and rump.
  const furCols = ['rgba(120, 83, 54, 0.85)', 'rgba(72, 47, 30, 0.9)', 'rgba(151, 110, 74, 0.5)'];
  for (let i = 0; i < 26; i++) {
    const a = 1.22 + (i / 25) * (TAU - 2.44);
    const bx = Math.cos(a) * 16.4;
    const by = Math.sin(a) * 9.1;
    const len = 1.15 + ((i * 5) % 4) * 0.4;
    const sweep = -0.18 + Math.sign(Math.cos(a)) * 0.22;
    ctx.strokeStyle = furCols[i % furCols.length];
    ctx.lineWidth = 1.4;
    ctx.beginPath();
    ctx.moveTo(bx * 0.94, by * 0.94);
    ctx.lineTo(bx + Math.cos(a + sweep) * len, by + Math.sin(a + sweep) * len);
    ctx.stroke();
  }
  // flowing coat strokes following the body
  for (let i = 0; i < 20; i++) {
    const sy = -7.4 + (i % 6) * 2.9;
    const sx = -13.4 + Math.floor(i / 6) * 8.0;
    ctx.strokeStyle = i % 3 === 0 ? 'rgba(170, 129, 90, 0.26)' : 'rgba(27, 16, 10, 0.45)';
    ctx.lineWidth = 0.85;
    ctx.beginPath();
    ctx.moveTo(sx, sy);
    ctx.quadraticCurveTo(sx + 4.6, sy + 0.5, sx + 8.2, sy - 0.4);
    ctx.stroke();
  }
  // scattered coarse hairs
  ctx.strokeStyle = 'rgba(190, 151, 108, 0.28)';
  ctx.lineWidth = 0.55;
  for (let i = 0; i < 24; i++) {
    const sx = -14.0 + ((i * 7) % 27);
    const sy = -8.2 + ((i * 5) % 17);
    ctx.beginPath();
    ctx.moveTo(sx, sy);
    ctx.lineTo(sx + 1.4, sy - 0.5);
    ctx.stroke();
  }

  // Shoulder hump, built from matted fur.
  const hump = ctx.createRadialGradient(3.0, -1.0, 1.0, 3.4, 0, 8.4);
  hump.addColorStop(0, 'rgba(132, 92, 60, 0.82)');
  hump.addColorStop(0.6, 'rgba(60, 39, 24, 0.55)');
  hump.addColorStop(1, 'rgba(48, 30, 18, 0)');
  ctx.fillStyle = hump;
  ctx.beginPath();
  ctx.ellipse(3.4, 0, 8.0, 6.4, 0, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = 'rgba(178, 136, 94, 0.3)';
  ctx.lineWidth = 0.8;
  for (let i = 0; i < 5; i++) {
    ctx.beginPath();
    ctx.moveTo(-1.0 + i * 2.0, -4.8 + i * 0.5);
    ctx.quadraticCurveTo(2.0 + i * 2.0, -1.0, 0.4 + i * 2.0, 3.8 - i * 0.4);
    ctx.stroke();
  }

  // Low-slung neck and heavy mane.
  ctx.fillStyle = '#352216';
  ctx.beginPath();
  ctx.ellipse(12.4, 0, 6.2, 7.1, 0, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = 'rgba(122, 85, 56, 0.85)';
  ctx.lineWidth = 1.0;
  for (let i = 0; i < 20; i++) {
    const a = 0.55 + (i / 19) * (TAU - 1.1);
    const bx = 12.4 + Math.cos(a) * 5.4;
    const by = Math.sin(a) * 6.2;
    const len = 1.3 + (i % 3) * 0.55;
    ctx.beginPath();
    ctx.moveTo(bx, by);
    ctx.lineTo(bx - 1.4 - Math.abs(Math.cos(a)) * 1.4, by + Math.sin(a) * len);
