    ctx.strokeStyle = 'rgba(255, 246, 219, 0.55)';
    ctx.lineWidth = 0.6;
    ctx.beginPath();
    ctx.moveTo(22.2, 8.5);
    ctx.quadraticCurveTo(28.4, 9.7, 33.8, 7.5);
    ctx.stroke();
    ctx.restore();
  }

