  ctx.strokeStyle = 'rgba(26, 15, 9, 0.9)';
  ctx.lineWidth = 1.2;
  for (let i = -2; i <= 2; i++) {
    ctx.beginPath();
    ctx.moveTo(22.6 + Math.abs(i) * 0.5, i * 2.45);
