function drawKraytBody(ctx, e, time) {
  const p = e.phase || 0;
  const tailSway = Math.sin(time * 2.7 + p);
  const tailSwayB = Math.sin(time * 2.7 + p - 0.8);
  const gait = Math.sin(time * 3.6 + p);
  const gaitB = Math.sin(time * 3.6 + p + Math.PI * 0.75);

  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  // --- tail ------------------------------------------------------------
  // Thick at the hips, tapering to a whip, with a dark dorsal stripe.
  const tail = ctx.createLinearGradient(-10, -6, -46, 8);
  tail.addColorStop(0, '#b68d59');
  tail.addColorStop(0.55, '#a37b4c');
  tail.addColorStop(1, '#87633e');
  ctx.fillStyle = tail;
  ctx.beginPath();
  ctx.moveTo(-10.0, -7.2);
  ctx.bezierCurveTo(-18.5, -8.0, -27.0, -5.0 + tailSway * 2.0, -37.0, -1.0 + tailSway * 5.0);
  ctx.bezierCurveTo(-43.0, 1.6 + tailSwayB * 6.2, -48.0, 3.0 + tailSwayB * 8.0, -51.0, 2.0 + tailSwayB * 9.0);
  ctx.bezierCurveTo(-45.0, 7.0 + tailSwayB * 7.0, -38.0, 8.2 + tailSway * 5.6, -30.0, 8.6 + tailSway * 4.0);
  ctx.bezierCurveTo(-22.0, 9.4 + tailSway * 2.6, -16.0, 9.4, -10.0, 7.2);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = '#5c3f27';
  ctx.lineWidth = 0.9;
  ctx.stroke();

  // dorsal stripe along the tail
  ctx.strokeStyle = '#805c35';
  ctx.lineWidth = 2.6;
  ctx.beginPath();
  ctx.moveTo(-10.5, 0);
  ctx.bezierCurveTo(-18.5, tailSway * 1.2, -28.0, 0.8 + tailSway * 3.0, -38.0, 1.6 + tailSwayB * 5.4);
  ctx.quadraticCurveTo(-45.0, 2.2 + tailSwayB * 7.0, -50.0, 2.1 + tailSwayB * 8.8);
  ctx.stroke();
  ctx.strokeStyle = 'rgba(238, 209, 164, 0.34)';
  ctx.lineWidth = 0.7;
  ctx.beginPath();
  ctx.moveTo(-11.0, -1.4);
  ctx.bezierCurveTo(-19.0, -0.6 + tailSway * 1.0, -28.0, -0.8 + tailSway * 2.4, -39.0, -0.6 + tailSwayB * 4.6);
  ctx.stroke();

  // broad transverse scale bands (not a fishbone of small plates)
  for (let i = 0; i < 6; i++) {
    const t = i / 5;
    const tx = -12.6 - t * 34.0;
    const ty = tailSwayB * (t * t * 7.2) + Math.sin(t * 2.8) * 0.8;
    const span = 5.4 * (1 - t * 0.74);
    ctx.strokeStyle = `rgba(86, 58, 32, ${0.28 + t * 0.16})`;
    ctx.lineWidth = 0.75;
    ctx.beginPath();
    ctx.moveTo(tx + 1.0, ty - span);
    ctx.quadraticCurveTo(tx - 1.6, ty, tx + 1.0, ty + span);
    ctx.stroke();
    ctx.strokeStyle = 'rgba(239, 212, 169, 0.28)';
    ctx.lineWidth = 0.5;
    ctx.beginPath();
    ctx.moveTo(tx + 2.0, ty - span * 0.8);
    ctx.quadraticCurveTo(tx - 0.4, ty, tx + 2.0, ty + span * 0.8);
    ctx.stroke();
  }

  // serrated tail ridge: small dark fins along the upper edge
  for (let i = 0; i < 6; i++) {
    const t = (i + 0.4) / 6;
    const tx = -12.0 - t * 34.0;
    const ty = tailSwayB * (t * t * 7.2) + Math.sin(t * 2.8) * 0.8;
    const span = 5.0 * (1 - t * 0.74);
    const size = 2.5 * (1 - t * 0.5);
    ctx.fillStyle = i % 2 ? '#7d5a34' : '#8c673d';
    ctx.beginPath();
    ctx.moveTo(tx + size * 0.5, ty - span);
    ctx.lineTo(tx - size * 0.9, ty - span - size * 1.2);
    ctx.lineTo(tx - size * 0.4, ty - span + size * 0.2);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = 'rgba(72, 48, 26, 0.55)';
    ctx.lineWidth = 0.3;
    ctx.stroke();
  }

  // --- legs ------------------------------------------------------------
  const legs = [
    { x: 11.5, y: -7.4, kx: 17.5, ky: -13.4, ax: 22.4, ay: -17.2, cx: 25.6, cy: -19.6, s: gait, front: true },
    { x: 11.5, y: 7.4, kx: 17.5, ky: 13.4, ax: 22.4, ay: 17.2, cx: 25.6, cy: 19.6, s: -gait, front: true },
    { x: -9.8, y: -7.6, kx: -14.2, ky: -13.2, ax: -18.0, ay: -16.8, cx: -21.2, cy: -19.4, s: -gaitB, front: false },
    { x: -9.8, y: 7.6, kx: -14.2, ky: 13.2, ax: -18.0, ay: 16.8, cx: -21.2, cy: 19.4, s: gaitB, front: false },
  ];
  for (const leg of legs) {
    const swing = leg.s * 1.0;
    ctx.strokeStyle = '#7b5a39';
    ctx.lineWidth = leg.front ? 8.2 : 9.2;
    ctx.beginPath();
    ctx.moveTo(leg.x, leg.y);
    ctx.lineTo(leg.kx + swing * 0.25, leg.ky);
    ctx.stroke();
    ctx.fillStyle = '#715234';
    ctx.beginPath();
    ctx.ellipse(leg.kx + swing * 0.25, leg.ky, 4.1, 3.6, 0, 0, TAU);
    ctx.fill();
    ctx.strokeStyle = '#8a6741';
    ctx.lineWidth = 5.4;
    ctx.beginPath();
    ctx.moveTo(leg.kx + swing * 0.25, leg.ky);
    ctx.lineTo(leg.ax + swing * 0.65, leg.ay);
    ctx.stroke();
    ctx.fillStyle = '#7b5a39';
    ctx.beginPath();
    ctx.ellipse(leg.ax + swing * 0.65, leg.ay, 3.2, 2.6, 0, 0, TAU);
    ctx.fill();
    const ang = Math.atan2(leg.cy - leg.ay, leg.cx - leg.ax);
    for (let c = -1; c <= 1; c++) {
      const a = ang + c * 0.3;
      ctx.fillStyle = '#dccaa6';
      ctx.beginPath();
      ctx.moveTo(leg.ax + swing * 0.65, leg.ay);
      ctx.lineTo(leg.ax + Math.cos(a) * 5.2 + swing * 0.65, leg.ay + Math.sin(a) * 5.2);
      ctx.lineTo(leg.ax + Math.cos(a + 0.2) * 3.1 + swing * 0.65, leg.ay + Math.sin(a + 0.2) * 3.1);
      ctx.closePath();
      ctx.fill();
      ctx.strokeStyle = '#7d613c';
      ctx.lineWidth = 0.35;
      ctx.stroke();
    }
    ctx.fillStyle = 'rgba(88, 60, 34, 0.4)';
    ctx.beginPath();
    ctx.ellipse(leg.kx + swing * 0.2, leg.ky, 2.8, 1.6, ang, 0, TAU);
    ctx.fill();
  }

  // --- body ------------------------------------------------------------
  // Tan flanks.
  const body = ctx.createLinearGradient(-6, -14, 16, 14);
  body.addColorStop(0, '#d9ba87');
  body.addColorStop(0.34, '#c39b66');
  body.addColorStop(0.72, '#a37b4d');
  body.addColorStop(1, '#87623d');
  ctx.fillStyle = body;
  ctx.beginPath();
  ctx.moveTo(-13.5, -6.2);
  ctx.bezierCurveTo(-10.0, -11.8, 2.0, -13.8, 10.0, -10.8);
  ctx.bezierCurveTo(14.2, -9.2, 16.8, -5.2, 17.2, 0);
  ctx.bezierCurveTo(16.8, 5.2, 14.2, 9.2, 10.0, 10.8);
  ctx.bezierCurveTo(2.0, 13.8, -10.0, 11.8, -13.5, 6.2);
  ctx.bezierCurveTo(-15.0, 3.0, -15.0, -3.0, -13.5, -6.2);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = '#5b3f26';
  ctx.lineWidth = 1.1;
  ctx.stroke();

  // Dark armored dorsal shield.
  const shield = ctx.createLinearGradient(-12, -9, 14, 9);
  shield.addColorStop(0, '#8d673d');
  shield.addColorStop(0.45, '#7a5732');
  shield.addColorStop(1, '#5f4327');
  ctx.fillStyle = shield;
  ctx.beginPath();
  ctx.moveTo(-12.4, -5.4);
  ctx.bezierCurveTo(-9.0, -9.4, 1.0, -10.6, 9.0, -8.4);
  ctx.bezierCurveTo(12.4, -7.4, 14.0, -4.0, 14.0, 0);
  ctx.bezierCurveTo(14.0, 4.0, 12.4, 7.4, 9.0, 8.4);
  ctx.bezierCurveTo(1.0, 10.6, -9.0, 9.4, -12.4, 5.4);
  ctx.bezierCurveTo(-13.6, 2.6, -13.6, -2.6, -12.4, -5.4);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = 'rgba(58, 38, 20, 0.75)';
  ctx.lineWidth = 0.8;
  ctx.stroke();

  // Overlapping armor scales on the shield.
  for (let i = 0; i < 5; i++) {
    const x = -9.0 + i * 4.8;
    for (const side of [-1, 1]) {
      ctx.fillStyle = i % 2 ? 'rgba(181, 139, 91, 0.7)' : 'rgba(157, 116, 72, 0.7)';
      ctx.beginPath();
      ctx.ellipse(x, side * 4.6, 3.2, 2.4, side * 0.22, 0, TAU);
      ctx.fill();
      ctx.strokeStyle = 'rgba(62, 40, 21, 0.6)';
      ctx.lineWidth = 0.45;
      ctx.stroke();
      ctx.strokeStyle = 'rgba(236, 207, 163, 0.3)';
      ctx.beginPath();
      ctx.moveTo(x - 2.0, side * 4.2);
      ctx.quadraticCurveTo(x, side * 3.5, x + 2.0, side * 4.2);
      ctx.stroke();
    }
  }
  // central ridge
  ctx.strokeStyle = 'rgba(56, 36, 19, 0.75)';
  ctx.lineWidth = 1.8;
  ctx.beginPath();
  ctx.moveTo(-11.4, 0);
  ctx.quadraticCurveTo(1.0, -1.0, 12.4, 0);
  ctx.stroke();
  ctx.strokeStyle = 'rgba(238, 209, 160, 0.35)';
  ctx.lineWidth = 0.6;
  ctx.beginPath();
  ctx.moveTo(-11.0, -1.6);
  ctx.quadraticCurveTo(1.0, -2.4, 12.0, -1.6);
  ctx.stroke();

  // shoulder and flank plates
  for (const side of [-1, 1]) {
    ctx.fillStyle = '#b18b58';
    ctx.beginPath();
    ctx.ellipse(10.0, side * 8.0, 3.8, 2.9, side * 0.35, 0, TAU);
    ctx.fill();
    ctx.strokeStyle = 'rgba(77, 51, 28, 0.65)';
    ctx.lineWidth = 0.5;
    ctx.stroke();
    ctx.strokeStyle = 'rgba(236, 207, 163, 0.28)';
    ctx.lineWidth = 0.7;
    ctx.beginPath();
    ctx.moveTo(-7.0, side * 10.0);
    ctx.quadraticCurveTo(3.0, side * 11.0, 12.0, side * 8.8);
    ctx.stroke();
  }

  // --- neck ------------------------------------------------------------
  ctx.fillStyle = '#a37b4d';
  ctx.beginPath();
  ctx.moveTo(9.0, -8.4);
  ctx.quadraticCurveTo(15.0, -7.4, 18.0, -4.4);
  ctx.lineTo(18.0, 4.4);
  ctx.quadraticCurveTo(15.0, 7.4, 9.0, 8.4);
  ctx.quadraticCurveTo(10.4, 0, 9.0, -8.4);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = '#5b3f26';
  ctx.lineWidth = 0.8;
  ctx.stroke();
  ctx.strokeStyle = 'rgba(77, 52, 28, 0.55)';
  ctx.lineWidth = 0.75;
  for (let i = 0; i < 3; i++) {
    ctx.beginPath();
    ctx.moveTo(10.4 + i * 2.2, -6.6 + i * 0.7);
    ctx.quadraticCurveTo(12.2 + i * 2.2, 0, 10.4 + i * 2.2, 6.6 - i * 0.7);
    ctx.stroke();
  }
  // neck frill spikes
  for (const side of [-1, 1]) {
    for (let i = 0; i < 3; i++) {
      const bx = 10.8 + i * 2.1;
      const by = side * (6.4 + i * 0.25);
      ctx.fillStyle = i % 2 ? '#8f6a3e' : '#7d5a34';
      ctx.beginPath();
      ctx.moveTo(bx, by);
      ctx.lineTo(bx - 2.4, by + side * 3.4);
      ctx.lineTo(bx + 1.2, by + side * 0.6);
      ctx.closePath();
      ctx.fill();
      ctx.strokeStyle = 'rgba(70, 47, 26, 0.55)';
      ctx.lineWidth = 0.3;
      ctx.stroke();
    }
  }

  // --- head ------------------------------------------------------------
  const hg = ctx.createLinearGradient(16, -10, 36, 10);
  hg.addColorStop(0, '#e0c28f');
  hg.addColorStop(0.5, '#c9a36e');
  hg.addColorStop(1, '#957046');
  ctx.fillStyle = hg;
  ctx.beginPath();
  ctx.moveTo(16.0, -8.6);
  ctx.quadraticCurveTo(22.0, -11.0, 27.0, -8.6);
  ctx.quadraticCurveTo(32.0, -6.0, 35.4, -2.6);
  ctx.quadraticCurveTo(36.8, 0, 35.4, 2.6);
  ctx.quadraticCurveTo(32.0, 6.0, 27.0, 8.6);
  ctx.quadraticCurveTo(22.0, 11.0, 16.0, 8.6);
  ctx.quadraticCurveTo(14.0, 0, 16.0, -8.6);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = '#5b3e24';
  ctx.lineWidth = 1.0;
  ctx.stroke();

  // brow ridges and eyes
  for (const side of [-1, 1]) {
    ctx.fillStyle = 'rgba(112, 78, 44, 0.68)';
    ctx.beginPath();
    ctx.ellipse(24.0, side * 5.8, 5.2, 2.1, side * 0.22, 0, TAU);
    ctx.fill();
    ctx.fillStyle = '#1b1009';
    ctx.beginPath();
    ctx.ellipse(25.0, side * 5.6, 2.2, 1.7, side * 0.25, 0, TAU);
    ctx.fill();
    ctx.fillStyle = '#ffc45f';
    ctx.beginPath();
    ctx.ellipse(25.1, side * 5.6, 1.5, 1.1, side * 0.25, 0, TAU);
