    ctx.beginPath();
    ctx.arc(25.55, side * 5.3, 0.26, 0, TAU);
    ctx.fill();
  }

  // muzzle, nostrils, jaw line
  ctx.fillStyle = 'rgba(227, 201, 158, 0.4)';
  ctx.beginPath();
  ctx.ellipse(32.0, 0, 3.2, 4.4, 0, 0, TAU);
  ctx.fill();
  ctx.fillStyle = '#3b2716';
  for (const side of [-1, 1]) {
    ctx.beginPath();
    ctx.ellipse(34.0, side * 1.6, 0.75, 0.45, side * 0.3, 0, TAU);
