import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');

const out = process.argv[2];
const mode = process.argv[3] || 'mix';
const browser = await chromium.launch({
  executablePath: '/usr/local/share/chromium/chrome-linux/chrome',
  headless: true,
  args: ['--no-sandbox', '--disable-dev-shm-usage'],
});
const page = await browser.newPage({ viewport: { width: 1600, height: 900 } });
const errors = [];
page.on('pageerror', e => errors.push('PAGEERROR ' + e.message));
page.on('console', m => { if (m.type() === 'error' && !m.text().includes('favicon')) errors.push('CONSOLE ' + m.text()); });
await page.goto('http://127.0.0.1:3002/?play=1', { waitUntil: 'load' });
await page.waitForTimeout(1200);

await page.evaluate((mode) => {
  const g = window.__game;
  g.paused = true;
  g.waveNumber = mode === 'boss' ? 25 : 12;
  g.phase = 'wave';
  g.waveActive = true;
  if (mode === 'boss') {
    g.spawnEnemy({ type: 'krayt', hp: 9000, speed: 27 });
    const k = g.enemies[g.enemies.length - 1];
    k.t = 0.34;
    g.positionEnemy(k);
    k.phase = 0.7;
  } else {
    const specs = [
      ['womprat', 0.20], ['womprat', 0.225], ['womprat', 0.25],
      ['bantha', 0.30], ['bantha', 0.335],
      ['krayt', 0.38],
    ];
    for (const [type, t] of specs) {
      g.spawnEnemy({ type, hp: 1000, speed: 40 });
      const e = g.enemies[g.enemies.length - 1];
      e.t = t;
      g.positionEnemy(e);
      e.phase = t * 7;
    }
  }
}, mode);

await page.waitForTimeout(1600);
await page.screenshot({ path: out });
console.log(errors.length ? errors.join('\n') : 'NO ERRORS');
await browser.close();

