import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1280, height: 760 }, deviceScaleFactor: 1 });
page.on('pageerror', e => console.error('PAGEERROR:', e.message));
await page.goto('http://localhost:8000/', { waitUntil: 'load' });
await page.waitForTimeout(700);
await page.evaluate(async () => {
  document.querySelectorAll('.screen').forEach(el => el.classList.add('hidden'));
  const { drawEnemy } = await import('/src/art.js');
  const wrap = document.createElement('div');
  wrap.style.cssText = 'position:fixed;inset:0;z-index:99999;background:#cf9f62;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px';
  const c = document.createElement('canvas');
  c.width = 1280; c.height = 700;
  wrap.appendChild(c);
  document.body.appendChild(wrap);
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#cf9f62'; ctx.fillRect(0,0,1280,700);
  // top row: game scale
  const gameRow = [
    ['womprat', 150, 150, 1.4],
    ['bantha', 430, 150, 1.4],
    ['krayt', 800, 150, 1.4],
    ['womprat', 1080, 150, 2.8],
  ];
  for (const [type, x, y, S] of gameRow) {
    const radius = type === 'womprat' ? 8.5 : type === 'bantha' ? 17 : 31;
    drawEnemy(ctx, { x, y, type, angle: 0, phase: 0.7, hp: 10, maxHp: 10, slowT: 0, hitFlash: 0, radius }, 1.6, S);
  }
  // bottom: large, angle 0 and pi/2
  const big = [
    ['womprat', 150, 430, 4.5, 0],
    ['bantha', 500, 430, 4.0, 0],
    ['krayt', 900, 440, 3.2, 0],
    ['krayt', 1150, 440, 3.2, Math.PI/2],
  ];
  for (const [type, x, y, S, angle] of big) {
    const radius = type === 'womprat' ? 8.5 : type === 'bantha' ? 17 : 31;
    drawEnemy(ctx, { x, y, type, angle, phase: 0.7, hp: 10, maxHp: 10, slowT: 0, hitFlash: 0, radius }, 1.6, S);
  }
});
await page.waitForTimeout(300);
await page.screenshot({ path: 'screenshots/creatures2.jpg', type: 'jpeg', quality: 90 });
await browser.close();
console.log('saved');
EOF
