// Enormous ivory horns: broad crescents that sweep out and forward from
// the skull, framing the head without crossing the muzzle.
for (const side of [-1, 1]) {
  ctx.save();
  ctx.scale(1, side);
  const horn = ctx.createLinearGradient(17, 4, 36, 17);
  horn.addColorStop(0, '#7f6544');
  horn.addColorStop(0.32, '#ab936b');
  horn.addColorStop(0.66, '#d6c199');
  horn.addColorStop(0.9, '#bfa67d');
  horn.addColorStop(1, '#8f734c');
  ctx.fillStyle = horn;
  ctx.beginPath();
  ctx.moveTo(17.6, 4.0);
  ctx.bezierCurveTo(22.2, 11.8, 28.8, 16.2, 35.4, 13.4);
  ctx.bezierCurveTo(31.0, 10.2, 24.8, 8.0, 19.4, 2.6);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = '#6a5336';
  ctx.lineWidth = 0.65;
  ctx.stroke();
  // growth rings
  ctx.strokeStyle = 'rgba(104, 79, 47, 0.4)';
  ctx.lineWidth = 0.42;
  for (let i = 0; i < 3; i++) {
    const t = 0.2 + i * 0.26;
    const bx = 19.8 + t * 11.8;
    const by = 6.2 + t * 7.4;
    ctx.beginPath();
    ctx.moveTo(bx - 0.9, by - 1.7);
    ctx.lineTo(bx + 0.9, by + 1.9);
    ctx.stroke();
  }
  // polished outer edge
  ctx.strokeStyle = 'rgba(255, 246, 219, 0.5)';
  ctx.lineWidth = 0.55;
  ctx.beginPath();
  ctx.moveTo(19.0, 6.4);
  ctx.quadraticCurveTo(26.6, 14.2, 34.4, 13.8);
  ctx.stroke();
  ctx.restore();
}

