  /* --- legs ---------------------------------------------------------- */
  const legs = [
    { hx: 10.0, hy: -8.0, kx: 15.0, ky: -15.0, ax: 20.5, ay: -20.5, s: gait, front: true },
    { hx: 10.0, hy: 8.0, kx: 15.0, ky: 15.0, ax: 20.5, ay: 20.5, s: -gait, front: true },
    { hx: -9.0, hy: -8.2, kx: -14.0, ky: -14.6, ax: -19.5, ay: -19.8, s: -gaitB, front: false },
