  ctx.bezierCurveTo(3.0, -8.4, 10.0, -6.8, 14.0, -3.8);
  ctx.bezierCurveTo(15.4, -1.3, 15.4, 1.3, 14.0, 3.8);
  ctx.bezierCurveTo(10.0, 6.8, 3.0, 8.4, -3.0, 8.0);
