      ctx.lineTo(bx + 0.6, by + side * len);
      ctx.lineTo(bx + 2.6, by);
      ctx.closePath();
      ctx.fill();
      ctx.strokeStyle = 'rgba(64, 43, 24, 0.6)';
      ctx.lineWidth = 0.45;
      ctx.stroke();
      ctx.fillStyle = 'rgba(236, 207, 163, 0.35)';
      ctx.beginPath();
      ctx.moveTo(bx - 1.2, by);
      ctx.lineTo(bx + 0.5, by + side * (len - 1.2));
