531: export function getMap(id) {
532:   return MAPS[id] || MAPS.tatooine;
533: }
534: 
535: /* ---------------- waves ---------------- */
536: 
537: export function makeWave(wave, mapId = 'tatooine') {
538:   const map = getMap(mapId);
539:   const growth = Math.pow(map.hpGrowth, wave - 1);
540:   const mix = map.mix;
541:   const specs = [];
542:   let delay = 0.6;
543:   const push = (type, count, hpMul = 1, gapOverride = 0) => {
544:     const def = ENEMY_TYPES[type];
545:     const gap = gapOverride || def.gap;
546:     for (let i = 0; i < count; i++) {
547:       delay += gap;
548:       specs.push({
549:         type,
550:         hp: Math.round(map.hpBase * growth * def.hp * hpMul),
551:         speed: def.speed,
552:         delay,
553:       });
554:     }
555:     delay += 0.35;
556:   };
557: 
558:   const bossEvery = map.bossEvery == null ? 10 : map.bossEvery;
559:   const bossWave = (bossEvery > 0 && wave % bossEvery === 0) || wave === map.waves;
560:   const isFinal = wave === map.waves;
561: 
562:   let lineCount = Math.round((6 + wave * 0.9) * mix.lineRate);
563:   let fastCount = wave >= mix.fastStart ? Math.max(1, Math.round((wave - 1) * mix.fastRate)) : 0;
564:   let heavyCount = wave >= mix.heavyStart ? Math.max(1, Math.floor((wave - mix.heavyStart + 1) * mix.heavyRate)) : 0;
565:   if (bossWave) {
566:     lineCount = Math.round(lineCount * 0.55);
567:     fastCount = Math.round(fastCount * 0.5);
568:     heavyCount = Math.max(1, Math.round(heavyCount * 0.5));
569:   }
570: 
571:   const roster = map.roster;
572: 
573:   // Opening skirmishers.
574:   const openingFast = fastCount ? Math.min(fastCount, Math.ceil(fastCount * 0.45)) : 0;
575:   if (openingFast) push(roster.fast, openingFast, 1, Math.max(0.28, ENEMY_TYPES[roster.fast].gap * 0.82));
576: 
577:   // Main line squads with short pauses between them.
578:   const squads = Math.max(1, Math.ceil(lineCount / 9));
579:   const perSquad = Math.ceil(lineCount / squads);
580:   for (let s = 0; s < squads; s++) {
581:     const count = Math.min(perSquad, lineCount - s * perSquad);
582:     if (count > 0) push(roster.line, count, 1);
583:     if (s < squads - 1) delay += 0.55;
584:   }
585: 
586:   // Heavy armour.
587:   if (heavyCount) {
588:     delay += 0.2;
589:     push(roster.heavy, heavyCount, 1, Math.max(0.8, ENEMY_TYPES[roster.heavy].gap * 0.86));
590:   }
591: 
592:   // Remaining fast units harass the back line.
593:   const restFast = fastCount - openingFast;
594:   if (restFast > 0) push(roster.fast, restFast, 1, Math.max(0.28, ENEMY_TYPES[roster.fast].gap * 0.8));
595: 
596:   if (bossWave) {
597:     const bossMul = isFinal ? (map.finalBossMul ?? 1.45) : 1;
598:     push(roster.boss, isFinal ? (map.finalBossCount ?? 2) : 1, bossMul, 1.6);
599:     if (isFinal) push(roster.heavy, 3, 1.3, 1.0);
600:   }
601: 
602:   return specs;
603: }
604: 
605: export function waveTotal(wave, mapId = 'tatooine') {
606:   return makeWave(wave, mapId).length;
607: }
608: 
609: export function waveReward(wave) {
610:   return 70 + wave * 10;
611: }
612: 
613: export function enemyReward(type, wave) {
614:   const def = ENEMY_TYPES[type];
615:   return Math.max(1, Math.round((1.6 + wave * 0.28) * def.reward));
616: }
