import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({channel:'chromium',headless:true,args:['--no-sandbox']});
const page = await browser.newPage({viewport:{width:1440,height:900},deviceScaleFactor:1});
const errors=[];
page.on('pageerror', e=>errors.push(e.message));
page.on('console', m=>{if(m.type()==='error') errors.push(m.text())});
const results=[];
for (const map of ['tatooine','hoth','mustafar']) {
  await page.goto('http://127.0.0.1:3001/',{waitUntil:'networkidle'});
  await page.waitForTimeout(500);
  await page.locator('#startMapBtn').click();
  await page.locator('#mapScreen:not(.hidden)').waitFor();
  await page.waitForTimeout(600);
  await page.locator(`.map-tile[data-map="${map}"]`).click();
  await page.waitForTimeout(250);
  await page.locator('#mapDockPlayBtn').click();
  await page.waitForTimeout(800);
  await page.locator('#nextWaveBtn').click();
  await page.waitForTimeout(2500);
  await page.screenshot({path:`/tmp/opencode/${map}-wave1-review.png`});
  results.push(await page.evaluate(()=>({map:document.querySelector('.map-name')?.innerText,canvas:!!document.querySelector('canvas'),canvasSize:[document.querySelector('canvas')?.width,document.querySelector('canvas')?.height],wave:document.querySelector('#waveLabel')?.innerText||document.querySelector('.wave-number')?.innerText})));
}
console.log(JSON.stringify({results,errors},null,2));
await browser.close();

