$('#btnPause').addEventListener('click', () => setPaused(!game.paused));
$('#resumeBtn').addEventListener('click', () => setPaused(false));
$('#restartBtn').addEventListener('click', () => restartRun());
function setPaused(paused) {
  if (!game.started) return;
  if (game.phase === 'victory' || game.phase === 'defeat') return;
  game.paused = paused;
  pauseModal.classList.toggle('hidden', !paused);
  if (paused) {
    cancelPlacement(true);
    closeInspector(true);
    audio.ui();
  } else {
    audio.ui();
  }
  syncUI(true);
}

function restartRun() {
  runFinished = false;
  pauseModal.classList.add('hidden');
  endScreen.classList.add('hidden');
  hideMenuScreens();
  game.reset();
  game.started = true;
  game.paused = false;
  game.speed = 1;
  selectedType = null;
  drag = null;
  closeInspector(true);
  setArmed(null);
  dragGhost.classList.add('hidden');
  placeHint.classList.add('hidden');
  syncUI(true);
  audio.ensure();
  toast('Wave 1 ready — drag a tower from the hangar', 'good');
}

function quitToMap() {
  runFinished = false;
  pauseModal.classList.add('hidden');
  endScreen.classList.add('hidden');
  cancelPlacement(true);
  closeInspector(true);
  game.reset();
  game.started = false;
  game.paused = false;
  selectedType = null;
  drag = null;
  setArmed(null);
  dragGhost.classList.add('hidden');
  placeHint.classList.add('hidden');
  showMenuScreen('map');
  syncUI(true);
}

$('#nextWaveBtn').addEventListener('click', () => {
  if (!game.started) return;
  if (game.phase !== 'build' || game.waveActive) return;
  cancelPlacement(true);
  const started = game.startWave();
  if (started) {
    audio.ui();
    toast(`Wave ${game.waveNumber} incoming`, 'bad');
    syncUI(true);
  }
});

$('#cancelPlace').addEventListener('click', () => cancelPlacement());

/* ---------------- start / end screens ---------------- */

let runFinished = false;

function startGame(auto = false) {
  audio.ensure();
  hideMenuScreens();
  endScreen.classList.add('hidden');
  pauseModal.classList.add('hidden');
  runFinished = false;
  lastIntelKey = '';
  game.setMap(selectedMap.id);
  game.reset();
  game.started = false;
  game.begin();
  game.paused = false;
  selectedType = null;
  drag = null;
  closeInspector(true);
  setArmed(null);

